const validStates = ['RECIBIDO','VALIDANDO_DOCUMENTO','REVISION_DOCUMENTO','PROCESANDO','ANALIZADO','ERROR','PENDIENTE_REVISION','EN_REVISION','ENTREVISTA','FINALIZADO','ON_HOLD','WITHDRAWN'];
let estado = $json.estado;
estado = (estado === undefined || estado === null || estado === '') ? null : String(estado).trim().toUpperCase();
if (estado !== null && !validStates.includes(estado)) throw new Error(`BOT_TOOL_INVALID_INPUT: estado desconocido '${estado}'`);
let limite = Number($json.limite);
if (!Number.isFinite(limite) || limite <= 0) limite = 15;
limite = Math.min(Math.trunc(limite), 50);
return [{ json: { estado, limite } }];
